def minimum_cost_to_merge_fruits(fruit_counts: List[int]) -> int:

    min_heap = MinHeap()
    for fruit in fruit_counts:
        min_heap.push((fruit, fruit_counts[fruit]))

    # Merge smallest heaps first until only one heap remains
    while len(min_heap) > 1:
        (fruit1, count1), (fruit2, count2) = min_heap.pop(), min_heap.pop()
        min_heap.push((fruit1, count1 + count2))

    # Total cost is the sum of the counts of all fruits
    return sum(min_heap[0][1] for fruit in min_heap)

